import {journey,goals,marketData,billingConfig,segments,funnel,trackingItems,kpis,implementation,preparation,matchOptions,eventMapping,sources,rsaLimits} from './google-ads-experience-data.js';
const root=document.querySelector('[data-google-experience]');
const $=s=>root.querySelector(s), $$=s=>[...root.querySelectorAll(s)];
const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const aliases=JSON.parse(document.getElementById('gx-legacy-anchors').textContent);
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const money=new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0});
const number=new Intl.NumberFormat('vi-VN',{maximumFractionDigits:1});
const renderFlow=items=>`<ol class="gx-flow">${items.map((x,i)=>`<li><span>0${i+1}</span><strong>${escape(x)}</strong></li>`).join('')}</ol>`;
const dl=rows=>`<dl class="gx-info-list">${rows.map(([a,b])=>`<div><dt>${escape(a)}</dt><dd>${escape(b)}</dd></div>`).join('')}</dl>`;
function press(selector,button){$$(selector).forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}
function bindSelect(selector,key,callback){const buttons=$$(selector);for(const b of buttons)b.addEventListener('click',()=>{press(selector,b);callback(b.dataset[key]);});if(buttons[0])callback(buttons[0].dataset[key]);}
const outer=$$('.ga-sheet-tabs [role=tab]'),campaigns=$$('.gx-campaign-tabs [role=tab]');
function activate(list,button,{focus=false}={}){for(const b of list){const selected=b===button;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;document.getElementById(b.getAttribute('aria-controls')).hidden=!selected;}if(focus)button.focus({preventScroll:true});if(innerWidth<700)button.scrollIntoView({block:'nearest',inline:'nearest',behavior:'instant'});refreshMotion();}
function wireTabs(list,outerList){list.forEach((b,i)=>{b.addEventListener('click',()=>{activate(list,b);history.replaceState(null,'','#'+b.getAttribute('aria-controls'));if(outerList)document.getElementById('ga-sheets').scrollIntoView({block:'start',behavior:'instant'});});b.addEventListener('keydown',ev=>{const index=ev.key==='ArrowRight'?(i+1)%list.length:ev.key==='ArrowLeft'?(i+list.length-1)%list.length:ev.key==='Home'?0:ev.key==='End'?list.length-1:null;if(index!==null){ev.preventDefault();activate(list,list[index],{focus:true});history.replaceState(null,'','#'+list[index].getAttribute('aria-controls'));}});});}
function navigateHash(scroll=true){let id;try{id=decodeURIComponent(location.hash.slice(1));}catch{return;}const a=aliases[id];let target=document.getElementById(id);if(!target&&a)target=document.getElementById(a.campaign?'ga-panel-'+a.campaign:'sheet-'+a.sheet);if(!target||!root.contains(target))return;const panel=target.closest('.ga-sheet-panel');if(panel)activate(outer,document.getElementById(panel.getAttribute('aria-labelledby')));const inner=target.closest('.ga-format-panel');if(inner)activate(campaigns,document.getElementById(inner.getAttribute('aria-labelledby')));for(let p=target.parentElement;p&&p!==root;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;if(scroll)requestAnimationFrame(()=>target.scrollIntoView({block:'start',behavior:'instant'}));}
// One scheduler; no work for hidden/offscreen/reduced-motion demos.
const demos=new Map($$('[data-motion]').map(el=>[el,{visible:false,paused:false,phase:0}]));
function refreshMotion(){for(const [el,s]of demos){const run=s.visible&&!s.paused&&!reduced.matches&&!document.hidden&&!el.closest('[hidden]');el.dataset.running=String(run);el.querySelectorAll('[data-step]').forEach(n=>n.classList.toggle('is-step',Number(n.dataset.step)===s.phase));}}
const observer=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{for(const e of entries)demos.get(e.target).visible=e.isIntersecting;refreshMotion();},{threshold:.1}):null;
for(const [el,s]of demos){if(observer)observer.observe(el);else s.visible=true;el.querySelector('.gx-motion-control').addEventListener('click',e=>{s.paused=!s.paused;e.currentTarget.setAttribute('aria-pressed',String(s.paused));e.currentTarget.textContent=s.paused?'Phát tiếp':'Tạm dừng';refreshMotion();});}
function updateReduced(){root.classList.toggle('gx-reduced',reduced.matches);for(const [el,s]of demos){const b=el.querySelector('.gx-motion-control');b.disabled=reduced.matches;b.textContent=reduced.matches?'Đã giảm chuyển động':s.paused?'Phát tiếp':'Tạm dừng';}refreshMotion();}
reduced.addEventListener('change',updateReduced);document.addEventListener('visibilitychange',refreshMotion);updateReduced();
const timer=setInterval(()=>{for(const [el,s]of demos)if(el.dataset.running==='true'){s.phase=(s.phase+1)%Number(el.dataset.count);el.dataset.phase=String(s.phase);}refreshMotion();},1800);
window.addEventListener('pagehide',()=>{for(const [el]of demos)el.dataset.running='false';});
window.addEventListener('pageshow',refreshMotion);
wireTabs(outer,true);wireTabs(campaigns,false);activate(outer,outer[0]);activate(campaigns,campaigns[0]);root.dataset.ready='true';navigateHash();window.addEventListener('hashchange',()=>navigateHash());window.addEventListener('popstate',()=>navigateHash());
root.addEventListener('click',ev=>{const a=ev.target.closest('a[href^="#"]');if(!a)return;const id=a.hash.slice(1);if(document.getElementById(id)||aliases[id]){ev.preventDefault();history.pushState(null,'',a.hash);navigateHash();}});
bindSelect('[data-journey]','journey',key=>$('#gx-journey-detail').textContent=journey[Number(key)][2]);
bindSelect('[data-goal]','goal',key=>{const g=goals.find(x=>x.id===key);$('#gx-goal-result').innerHTML=`<span class="page-kicker">ĐANG XEM / ${escape(g.title)}</span>${renderFlow(g.flow)}${dl([['Cách chạy cân nhắc',g.campaign],['Nút liên hệ',g.cta],['Đo điều gì?',g.measure],['Cần chuẩn bị',g.needs]])}`;});
bindSelect('[data-choices="match"] [data-choice]','choice',key=>{const m=matchOptions.find(x=>x[0]===key);$('#gx-match-detail').innerHTML=`<strong>${escape(m[2])}</strong><p>${escape(m[3])}</p>`;});
$('#gx-negative').addEventListener('change',e=>{$('#gx-negative-status').textContent=e.target.checked?'Trong ví dụ: loại vì chứa cụm phủ định “tuyển dụng”.':'Có dấu hiệu lệch nhu cầu mua dịch vụ';$('.gx-query-row').classList.toggle('is-excluded',e.target.checked);});
function copyPreview(){const h=$('#gx-ad-headline'),d=$('#gx-ad-description');$('#gx-copy-title').textContent=h.value||'Tiêu đề mẫu';$('#gx-copy-description').textContent=d.value||'Mô tả mẫu';$('#gx-headline-count').textContent=`${h.value.length}/${rsaLimits.headline} ký tự`;$('#gx-description-count').textContent=`${d.value.length}/${rsaLimits.description} ký tự`;}
$('#gx-ad-headline').addEventListener('input',copyPreview);$('#gx-ad-description').addEventListener('input',copyPreview);copyPreview();
const videoFormats={instream:'Video trong trải nghiệm xem. Có loại có thể bỏ qua và không bỏ qua, với yêu cầu và cách tính khác nhau; xác định loại trước khi chốt thời lượng.',infeed:'Video được khám phá trong feed/kết quả có hỗ trợ. Thumbnail, tiêu đề và nội dung cần tạo lý do để người xem chọn xem.',shorts:'Trải nghiệm video dọc; chuẩn bị bố cục 9:16, giữ nội dung quan trọng tránh vùng giao diện và giải thích giá trị nhanh.',bumper:'Quảng cáo ngắn tối đa 6 giây theo tài liệu định dạng video của Google. Tập trung một thông điệp; không cố nhét toàn bộ bài giới thiệu.'};
bindSelect('[data-choices="videoformat"] [data-choice]','choice',key=>$('#gx-video-format').textContent=videoFormats[key]);
const locationInfo={country:'Xem Việt Nam như phạm vi thảo luận khi doanh nghiệp có thể phục vụ cả nước. Đây không phải dự báo reach.',province:'Chọn tỉnh/thành doanh nghiệp thực sự phục vụ trong danh sách Google hỗ trợ.',area:'Mức địa lý nhỏ hơn phụ thuộc dữ liệu và loại chiến dịch. Đối chiếu vùng giao hàng hoặc điểm phục vụ.',radius:'Bán kính quanh địa điểm có thể sử dụng khi được hỗ trợ. Cần kiểm tra điều kiện và tùy chọn vị trí; không coi đó là hàng rào định vị tuyệt đối.'};
bindSelect('[data-choices="location"] [data-choice]','choice',key=>$('#gx-location-detail').textContent=locationInfo[key]);
function renderMarket(){const approved=Boolean(marketData.source&&marketData.lastUpdated&&marketData.metricDefinition);for(const el of $$('[data-market]')){const v=marketData[el.dataset.market];if(approved&&Number.isFinite(v)&&v>=0){el.textContent=number.format(v);el.nextElementSibling.textContent=marketData.metricDefinition;}else{el.textContent='—';el.nextElementSibling.textContent='Chưa có dữ liệu được duyệt';}}
if(approved&&$('#gx-market-source'))$('#gx-market-source').textContent=`Nguồn: ${marketData.source} · Cập nhật: ${marketData.lastUpdated} · ${marketData.geography}. ${marketData.metricDefinition}`;
for(const fig of $$('[data-chart]')){const rows=marketData[fig.dataset.chart];if(!approved||!Array.isArray(rows)||!rows.length||rows.some(x=>!x.label||!Number.isFinite(x.value)||x.value<0||x.value>100))continue;const body=document.createElement('div');body.className='gx-real-chart';for(const r of rows){const row=document.createElement('div');const label=document.createElement('span');label.textContent=r.label;const bar=document.createElement('i');bar.style.setProperty('--value',r.value+'%');const value=document.createElement('b');value.textContent=number.format(r.value)+'%';row.append(label,bar,value);body.append(row);}fig.querySelector('.gx-chart-empty').replaceWith(body);}
if(!approved&&['localhost','127.0.0.1'].includes(location.hostname))console.info('[Google Ads config] Market metrics are unapproved; empty states shown. Add source, lastUpdated, metricDefinition and verified values to publish numbers.');}
renderMarket();
bindSelect('[data-choices="segment"] [data-choice]','choice',key=>{const s=segments.find(x=>x[0]===key);$('#gx-segment-detail').innerHTML=`<span class="page-kicker">NHÓM KHÁCH NÀY LÀ AI?</span><h3>${escape(s[1])}</h3><p>${escape(s[2])}</p><strong>${escape(s[3])}</strong>`;});
bindSelect('[data-funnel]','funnel',key=>{const f=funnel.find(x=>x[0]===key);$('#gx-funnel-detail').innerHTML=`<span class="page-kicker">${escape(f[1])} / ${escape(f[2])}</span>${dl([['Mục tiêu',f[3]],['Nói điều gì?',f[4]],['Mời khách làm gì?',f[5]],['Phương án',f[6]]])}`;});
const audienceCases={search:['Tìm “thiết kế website”','Search ad khớp intent','Trang giải pháp','Nhận tư vấn'],visit:['Xem dịch vụ, chưa gửi form','Tệp hợp lệ / kiểm tra loại trừ','Display/GDN ở nơi hỗ trợ','Xem thêm thông tin'],crm:['Dữ liệu khách được phép dùng','Điều kiện Customer Match / đối sánh','Chiến dịch hỗ trợ','Nội dung tiếp nối phù hợp']};
bindSelect('[data-choices="audiencecase"] [data-choice]','choice',key=>$('#gx-audience-case').innerHTML=renderFlow(audienceCases[key])+'<p>Khả năng tiếp cận phụ thuộc chính sách, loại chiến dịch và dữ liệu đủ điều kiện.</p>');
const intents={high:['Nhận báo giá · Gọi tư vấn · Đặt lịch · Kiểm tra giá · Yêu cầu proposal','Điểm đến cần đủ thông tin và đội ngũ sẵn sàng tiếp nhận nhu cầu.'],medium:['Xem mẫu · Xem giải pháp · Xem bảng giá · Xem dự án đã xác minh','Giúp khách so sánh trước khi yêu cầu trao đổi; không dẫn tới bằng chứng chưa có.'],awareness:['Tìm hiểu thêm · Xem video · Khám phá giải pháp','Hành động nhẹ để hiểu lợi ích trước. CTA vẫn cần dẫn tới nội dung có ích.']};
bindSelect('[data-choices="intent"] [data-choice]','choice',key=>$('#gx-intent-detail').innerHTML=`<strong>${intents[key][0]}</strong><p>${intents[key][1]}</p>`);
function calculator(){const daily=$('#gx-daily'),days=$('#gx-days'),cpl=$('#gx-cpl');const filled=daily.value!==''&&days.value!=='';const valid=filled&&daily.validity.valid&&days.validity.valid&&Number.isFinite(daily.valueAsNumber)&&Number.isFinite(days.valueAsNumber);let spend=valid?daily.valueAsNumber*days.valueAsNumber:null;let total=spend;const rows=[];let bad=false;for(const input of $$('[data-cost]'))if(!input.disabled){if(input.value===''||!input.validity.valid||!Number.isFinite(input.valueAsNumber)){bad=true;continue;}if(total!==null)total+=input.valueAsNumber;rows.push([input.getAttribute('aria-label').replace('Số tiền ',''),input.valueAsNumber]);}
const cplPresent=cpl.value!=='';const cplValid=cplPresent&&cpl.validity.valid&&Number.isFinite(cpl.valueAsNumber)&&cpl.valueAsNumber>0;const unsafe=(total!==null&&!Number.isSafeInteger(Math.ceil(total)));const baseError=filled&&!valid;$('#gx-budget-error').textContent=unsafe?'Tổng tiền quá lớn để tính chính xác.':bad?'Nhập số tiền hợp lệ cho từng khoản đã chọn.':baseError?'Ngân sách từ 0 tới 1.000 tỷ; số ngày là số nguyên từ 1 tới 366.':cplPresent&&!cplValid?'Chi phí cho một yêu cầu phải lớn hơn 0 và không quá 1.000 tỷ đồng.':'';$('#gx-spend').textContent=spend!==null&&!unsafe?money.format(spend):'—';$('#gx-leads').textContent=spend!==null&&cplValid&&!unsafe?number.format(spend/cpl.valueAsNumber):'—';$('#gx-total').textContent=total!==null&&!bad&&!unsafe?money.format(total):'—';$('#gx-cost-breakdown').innerHTML=rows.map(([label,value])=>`<div><span>${escape(label)}</span><b>${money.format(value)}</b></div>`).join('');$('#gx-tax-status').textContent=$('[data-cost-enable="tax"]').checked&&!bad?'Thuế/phí theo số bạn nhập. Cần kiểm tra lại trên hóa đơn.':'Tổng chưa gồm khoản thuế/phí bạn chưa nhập.';}
$('#gx-budget-form').addEventListener('submit',e=>e.preventDefault());$('#gx-budget-form').addEventListener('input',calculator);for(const c of $$('[data-cost-enable]'))c.addEventListener('change',()=>{$(`[data-cost="${c.dataset.costEnable}"]`).disabled=!c.checked;calculator();});calculator();
if(billingConfig.source&&billingConfig.lastUpdated)$('#gx-tax-source').textContent=`Nguồn cấu hình: ${billingConfig.source} · ${billingConfig.lastUpdated}. Xác nhận theo hồ sơ thực tế.`;
bindSelect('[data-tracking]','tracking',key=>{const t=trackingItems.find(x=>x.id===key),s=sources[t.source];$('#gx-tracking-detail').innerHTML=`<div><span class="page-kicker">CÔNG CỤ NÀY DÙNG ĐỂ LÀM GÌ?</span><h3>${escape(t.name)}</h3><p>${escape(t.purpose)}</p></div>${dl([['Dùng khi nào?',t.requiredWhen],['Lưu ý',t.optionalWhen],['Cần có',t.input],['Nhận được',t.output]])}<a href="https://support.google.com/google-ads/answer/${s[0]}?hl=vi" target="_blank" rel="noopener noreferrer">${escape(s[1])} ↗</a>`;});
bindSelect('[data-kpi]','kpi',key=>{const k=kpis.find(x=>x[0]===key);$('#gx-kpi-diagnostic').innerHTML=`<div><span class="page-kicker">ĐỌC ${escape(k[1])}</span><h3>${escape(k[2])}</h3><p>${escape(k[3])}</p></div><aside><strong>Nên kiểm tra ở đâu?</strong><p>${escape(k[4])}</p></aside>`;});
bindSelect('[data-timeline]','timeline',key=>{const [t,work,out]=implementation[Number(key)];$('#gx-timeline-detail').innerHTML=`<div class="gs-document-head"><span>POWAI / HỒ SƠ CÔNG VIỆC</span><small>BƯỚC ${String(Number(key)+1).padStart(2,'0')}</small></div><h3>${escape(t)}</h3><div class="gs-document-row"><b>☐ Công việc cần thực hiện</b><p>${escape(work)}</p></div><div class="gs-document-row"><b>▤ Tài liệu / đầu ra bàn giao</b><p>${escape(out)}</p></div><div class="gs-document-sign">Người thực hiện · Người duyệt · Bằng chứng hoàn tất<span>Chốt khi triển khai thực tế</span></div>`;});
for(const c of $$('[data-prep]'))c.addEventListener('change',()=>$('#gx-prep-count').textContent=`${$$('[data-prep]:checked').length} / ${preparation.length} mục đã đánh dấu`);
// UI-only lead form: never submit or transmit customer input.
$('#ga-inquiry-form')?.addEventListener('submit',e=>e.preventDefault());
// Manual replicas let visitors read and click at their own pace.
for(const replica of $$('[data-replica]')){
  let current=1;
  const scenes=[...replica.querySelectorAll('[data-replica-scene]')];
  const select=step=>{current=step;for(const scene of scenes)scene.hidden=Number(scene.dataset.replicaScene)!==step;replica.querySelectorAll('.gr-steps [data-replica-go]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.replicaGo)===step)));replica.querySelector('.gr-explanation').textContent=scenes[step].dataset.explanation;replica.querySelector('[data-replica-next]').textContent=step===3?'Xem lại trên Google ↺':step===0?'Xem quảng cáo trên Google →':step===1?'Xem trang đích →':'Thử chuyển đổi →';};
  const contactData={call:['Hotline','☎','Cuộc gọi điện thoại','Nhấp hotline → tín hiệu ý định gọi','Nhấp số điện thoại chưa chứng minh cuộc gọi đã kết nối hoặc có khách phù hợp. Đối chiếu tổng đài/nhật ký và CRM; báo cáo cuộc gọi Google tùy điều kiện hỗ trợ.','Mô phỏng đã tiếp nhận cuộc gọi'],zalo:['Zalo','Z','Hội thoại với doanh nghiệp','Nhấp Zalo → mở kênh liên hệ','Click nút Zalo trên website có thể đo bằng sự kiện tùy chỉnh. Hội thoại thực và chất lượng lead cần đối soát Zalo/CRM hoặc tích hợp hợp lệ; Google tag không tự đọc nội dung chat.','Mô phỏng đã tiếp nhận tin nhắn'],messenger:['Messenger','↗','Hội thoại với doanh nghiệp','Nhấp Messenger → mở kênh liên hệ','Click Messenger chưa đồng nghĩa gửi tin. Đối soát hội thoại với đội tư vấn/CRM; chỉ đồng bộ kết quả về Ads khi có tích hợp và cơ sở dữ liệu phù hợp.','Mô phỏng đã tiếp nhận tin nhắn'],form:['Form','▤','Yêu cầu tư vấn','Mở form → chưa gửi yêu cầu','Gửi sự kiện lead khi hệ thống xác nhận tiếp nhận thành công. Tránh đo chỉ bằng nhấp nút; chống gửi trùng và lọc spam.','Mô phỏng gửi yêu cầu thành công']};
  function contact(key){const host=replica.querySelector('[data-contact-screen]');if(!host)return;const d=contactData[key];replica.dataset.contact=key;replica.querySelectorAll('[data-contact]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.contact===key)));host.innerHTML='<small>'+d[2]+'</small><div class="gr-avatar">'+d[1]+'</div><h3>'+d[0]+' doanh nghiệp</h3>'+(key==='call'?'<p>09xx xxx xxx · Số minh họa</p><div class="gr-dialpad">1 &nbsp; 2 &nbsp; 3<br>4 &nbsp; 5 &nbsp; 6<br>7 &nbsp; 8 &nbsp; 9</div>':key==='form'?'<div class="gr-form-example"><span>Họ và tên <b>Khách hàng mẫu</b></span><span>Nhu cầu <b>Tư vấn website doanh nghiệp</b></span></div>':'<div class="gr-chat-bubble">Tôi cần tư vấn thiết kế website cho doanh nghiệp.</div><div class="gr-chat-compose">Nhập tin nhắn… &nbsp; ➤</div>')+'<button type="button" class="gr-primary" data-contact-confirm>'+d[5]+'</button>';replica.querySelector('[data-contact-status]').textContent=d[3];replica.querySelector('[data-contact-note]').textContent=d[4];replica.querySelector('.gr-contact-layout .gr-event').classList.remove('is-complete');}
  replica.addEventListener('click',event=>{const open=event.target.closest('[data-contact-open]');if(open){select(3);contact(open.dataset.contactOpen);return;}const choice=event.target.closest('button[data-contact]');if(choice){contact(choice.dataset.contact);return;}if(event.target.closest('[data-contact-confirm]')){replica.querySelector('[data-contact-status]').textContent='✓ Tiếp nhận mẫu thành công → cần đánh giá lead trong CRM';replica.querySelector('.gr-contact-layout .gr-event').classList.add('is-complete');return;}const surface=event.target.closest('[data-surface]');if(surface){if(![...replica.querySelectorAll('[data-surface-panel]')].some(p=>p.dataset.surfacePanel===surface.dataset.surface))return;replica.querySelectorAll('[data-surface-panel]').forEach(panel=>panel.hidden=panel.dataset.surfacePanel!==surface.dataset.surface);replica.querySelectorAll('.gr-surfaces [data-surface]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.surface===surface.dataset.surface)));return;}if(event.target.closest('[data-video-skip]')){const player=event.target.closest('.gr-youtube-player');player.innerHTML='<div class="gr-skipped"><span>▷</span><h3>Video nội dung tiếp tục</h3><p>Khách đã bỏ qua quảng cáo. Không ghi nhận đây là một đơn hàng.</p></div>';return;}
  });
  replica.addEventListener('click',event=>{const go=event.target.closest('[data-replica-go]');if(go){if(go.dataset.replicaProduct!==undefined){const i=Number(go.dataset.replicaProduct),color=['#357a88','#b59580','#434b56','#8a9d87'][i],price=i===2?'390.000 ₫':'350.000 ₫',name='Bình giữ nhiệt NOVA 500 ml'+['',' – Be',' – Đen',' – Xanh nhạt'][i];replica.querySelector('.gr-product-page h3').textContent=name;replica.querySelector('.gr-price').textContent=price;replica.querySelector('.gr-product-page h3 + strong + p').innerHTML=['Màu xanh','Màu be','Màu đen','Màu xanh nhạt'][i]+' · Dung tích 500 ml<br>Tình trạng: còn hàng (ví dụ)';replica.querySelector('.gr-checkout .gr-feed-product b').textContent=name;replica.querySelector('.gr-checkout .gr-feed-product strong').textContent=price+' (giá ví dụ)';replica.querySelectorAll('.gr-product-page svg path:first-of-type,.gr-checkout svg path:first-of-type').forEach(path=>path.setAttribute('fill',color));replica.querySelector('[data-replica-status]').textContent='Chưa ghi nhận chuyển đổi';replica.querySelector('.gr-event').classList.remove('is-complete');}select(Number(go.dataset.replicaGo));return;}if(event.target.closest('[data-replica-next]'))select(current===3?1:current+1);if(event.target.closest('[data-replica-complete]')){replica.querySelector('[data-replica-status]').textContent=replica.dataset.replica==='app'?'✓ Mua trong app thành công → purchase':'✓ Đơn mẫu thành công → purchase';replica.querySelector('.gr-event').classList.add('is-complete');}});
}
const sheetSims=JSON.parse(document.getElementById('gs-simulation-data').textContent);
function updateDemoScope(){const host=$('[data-sheet-sim="demographics"]');const ages=[...host.querySelectorAll('[data-demo-age]:checked')].map(n=>n.value),genders=[...host.querySelectorAll('[data-demo-gender]:checked')].map(n=>n.value);host.querySelector('[data-demo-summary]').textContent=(!ages.length||!genders.length)?'Chưa chọn đủ nhóm tuổi và giới tính. Hãy xem lại phạm vi.':'Tuổi: '+ages.join(', ')+' · Giới tính: '+genders.join(', ');}
$('[data-sheet-sim="demographics"]').addEventListener('change',updateDemoScope);updateDemoScope();
for(const host of $$('[data-sheet-sim]'))host.addEventListener('click',e=>{const button=e.target.closest('[data-sim-choice]');if(button){const [type,key]=button.dataset.simChoice.split(':');host.querySelectorAll('[data-sim-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));if(type==='audience'){const row=sheetSims.audienceRows[key];for(const [selector,value] of [['name',row[0]],['include',row[1]],['exclude',row[2]],['cta',row[3]]])host.querySelector('[data-audience-'+selector+']').textContent=value;}if(type==='compare'){const row=sheetSims.cases[key];for(const [selector,value] of [['heading',row[0]],['query',row[1]],['title',row[2]],['explain',row[3]]])host.querySelector('[data-case-'+selector+']').textContent=value;host.dataset.case=key;host.querySelector('[data-case-label]').textContent=key==='search'?'Được tài trợ / ví dụ Search':key==='discovery'?'Nội dung trực quan / ví dụ feed':'Thông điệp tiếp nối / ví dụ';}if(type==='events'){const row=sheetSims.events[key];for(const [selector,value] of [['name',row[0]],['action',row[1]],['note',row[2]],['follow',row[3]]])host.querySelector('[data-event-'+selector+']').textContent=value;host.querySelector('[data-event-outcome]').textContent='Chưa biết đây có phải khách có nhu cầu phù hợp hay không.';host.classList.remove('gs-qualified');}}if(e.target.closest('[data-event-qualify]')){host.querySelector('[data-event-outcome]').textContent='✓ Ví dụ: nhân viên đã xác nhận khách có nhu cầu phù hợp. Kết quả chỉ gửi về Google Ads khi hệ thống đã được kết nối.';host.classList.add('gs-qualified');}});

$('[data-budget-example]').addEventListener('click',()=>{$('#gx-daily').value='500000';$('#gx-days').value='30';$('#gx-cpl').value='250000';calculator();});
$('[data-budget-clear]').addEventListener('click',()=>{$('#gx-budget-form').reset();for(const input of $$('[data-cost]'))input.disabled=true;calculator();});

$('#gc-kpi-select')?.addEventListener('change',e=>{const b=$$('[data-kpi]').find(x=>x.dataset.kpi===e.target.value);b?.click();});
const audienceStages=$('[data-audience-stages]');
if(audienceStages){const data=JSON.parse($('#ab-audience-data').textContent);function showEarned(key){const r=data.earned[key];for(const [i,name]of ['title','who','when','message','exclude','setup'].entries())audienceStages.querySelector('[data-earned-'+name+']').textContent=r[i];}$('#ab-earned-select').addEventListener('change',e=>showEarned(e.target.value));showEarned('visitors');audienceStages.addEventListener('click',e=>{const stage=e.target.closest('[data-audience-stage]');if(stage){const value=stage.dataset.audienceStage;audienceStages.querySelectorAll('[data-audience-view]').forEach(p=>p.hidden=p.dataset.audienceView!==value);audienceStages.querySelectorAll('.ab-switch button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.audienceStage===value)));}const plan=e.target.closest('[data-audience-plan]');if(plan){const r=data.plans[plan.dataset.audiencePlan];audienceStages.querySelectorAll('[data-audience-plan]').forEach(b=>b.setAttribute('aria-pressed',String(b===plan)));for(const [key,text]of [['title',r[0]],['example',r[1]],['prep',r[2]]])audienceStages.querySelector('[data-plan-'+key+']').textContent=text;}});}
